#include <bits/stdc++.h>
using namespace std;
#define _USE_MATH_DEFINES

#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>
using namespace __gnu_pbds;
template <typename T>
using ordered_set = tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;

#define rep(i, a, b) for(int i = (a); i < (b); ++i)
#define repr(i, a, b) for(int i = (b)-1; i >= (a); --i)
#define all(x) (x).begin(), (x).end()

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;
typedef vector<pt> pol;
typedef vector<int> vi;

const char nl = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1000000007LL;
const ld EPS = 1e-10;
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int T = 99;
const int C = 12;
namespace Flow {
	const int N = 50*T + 2;

  struct Edge { int v, rev; ll flow, cap, cost; };
  vector<Edge> graph[N]; int deg[N]; ll minCost;
  void reset(int n=N) { minCost=0; fill(deg,deg+n,0); fill(graph,graph+n,vector<Edge>()); }
  void connect(int u, int v, ll cap=1, ll cost=0) { minCost = max(minCost,cap);
    graph[u].emplace_back(v, deg[v]++, 0, cap, cost);
    graph[v].emplace_back(u, deg[u]++, 0, 0, -cost); }

  bool visited[N]; int parent[N]; ll potential[N], dist[N];
  void setup_potential(int n) { fill(potential, potential+n, 0);
    for(int step=1; step<n; step++) for(int node=0; node<n; node++) for(const Edge& e:graph[node])
      if(e.cap) potential[e.v] = min(potential[e.v], potential[node] + e.cost); }
  ll augment(int src, int dst, ll& totalCost, int nodes, bool useQueue) {
    fill(visited, visited+nodes, false); fill(dist, dist+nodes, INF); dist[src] = 0;
    if(useQueue) {
      queue<int> q; q.push(src);
      while(!q.empty()) {
        int u = q.front(); q.pop();
        if(visited[u]) continue;
        visited[u] = true;
        for(const Edge& e:graph[u]) {
          if (e.flow < e.cap && dist[e.v] > dist[u] + potential[u] - potential[e.v] + e.cost) {
            dist[e.v] = dist[u] + potential[u] - potential[e.v] + e.cost; parent[e.v] = e.rev;
            q.push(e.v); } } }
    } else {
      for(int u = src; u != -1; ) { visited[u] = true;
        for(const Edge& e:graph[u]) {
          if (e.flow < e.cap && dist[e.v] > dist[u] + potential[u] - potential[e.v] + e.cost) {
            dist[e.v] = dist[u] + potential[u] - potential[e.v] + e.cost; parent[e.v] = e.rev; } }
        u = -1; ll best = INF;
        for(int i=0; i<nodes; i++) if(!visited[i] && dist[i]<best) best = dist[u=i]; }
    }
    if (dist[dst] >= INF) return 0;
    ll bottleneck = INF;
    for(int node = dst; node != src; ) {
      const Edge& revEdge = graph[node][parent[node]];
      bottleneck = min(bottleneck, graph[revEdge.v][revEdge.rev].cap - graph[revEdge.v][revEdge.rev].flow);
      node = revEdge.v;
    }
    for(int node = dst; node != src; ) {
      Edge& revEdge = graph[node][parent[node]];
      Edge& forwardEdge = graph[revEdge.v][revEdge.rev];
      forwardEdge.flow += bottleneck;
      revEdge.flow -= bottleneck;
      totalCost += bottleneck * forwardEdge.cost;
      node = revEdge.v;
    }
    for(int i=0; i<nodes; i++) { potential[i] = min(INF, dist[i]+potential[i]); }
    return bottleneck;
  }
  ll min_cost_max_flow(int src, int dst, ll& totalCost, int nodes=N, bool useQueue=false) {
    setup_potential(nodes); ll totalFlow = totalCost = 0;
    while(ll df=augment(src, dst, totalCost, nodes, useQueue)) { totalFlow += df; }
    return totalFlow; }
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr); cout.tie(nullptr);
	cout << fixed << setprecision(10);

	int n,m,k,c,d;
	cin>>n>>m>>k>>c>>d;

	const int source = 0;
	const int sink = n*T+1;

	for(int i=0;i<k;i++) {
		int a;
		cin>>a;
		Flow::connect(source, a, 1, 0);
	}
	for(int t=0;t<T;t++) {
		Flow::connect(1+t*n, sink, INF, 0);
		if(t>0) {
			for(int i=1;i<=n;i++) {
				Flow::connect(i+(t-1)*n, i+t*n, INF, c);
			}
		}
	}

	for(int i=0;i<m;i++) {
		int a, b;
		cin >> a >> b;
		for(int j=0;j<C;j++) {
			int cost = (j+1)*(j+1) - j*j;
			for(int t=1;t<T;t++) {
				Flow::connect(a+(t-1)*n, b+t*n, 1, cost*d + c);
				Flow::connect(b+(t-1)*n, a+t*n, 1, cost*d + c);
			}
		}
	}

	ll totalCost, flow = Flow::min_cost_max_flow(source, sink, totalCost, sink+1, true);
	assert(flow==k);
	cout << totalCost << nl;

	return 0;
}
